"""Render measured reports only after every required automated gate has completed."""
import argparse,json,re,hashlib
from pathlib import Path

def main():
 ap=argparse.ArgumentParser();ap.add_argument('validation',type=Path);ap.add_argument('campaign_summary',type=Path);ap.add_argument('--output',type=Path,required=True);a=ap.parse_args();reports=a.validation/'reports';a.output.mkdir(parents=True,exist_ok=True)
 names=['cinematic','stability','compatibility','production','bridge','mobile_functional','migrate_phase1','migrate_phase2','migrate_phase3','migrate_phase3_loss','migrate_phase35','static','performance','streaming'];tests={n:json.loads((reports/(n+'.json')).read_text()) for n in names};assert all(r['passed'] for r in tests.values()),[n for n,r in tests.items() if not r['passed']]
 node=(reports/'node.txt').read_text();assert re.search(r'fail 0\b',node) and re.search(r'skipped 0\b',node);count=int(re.search(r'tests (\d+)',node)[1]);campaigns=json.loads(a.campaign_summary.read_text());assert campaigns['passed'];manifest=json.loads((a.validation/'tested/ICARUS_Cinematic_Refinement_Phase3_5_Lite/BUILD_MANIFEST.json').read_text());assert all(v['runtime_sha256']==json.loads((a.validation/'tested/ICARUS_Cinematic_Refinement_Phase3_5_Lite/BUILD_MANIFEST.json').read_text())['runtime_files'] for v in campaigns['campaigns'].values())
 missing=['Native Windows BAT/input','Physical Android/Wi-Fi and Galaxy Tab S5e/Samsung TV','Firefox/Safari','Antivirus engine/penetration testing','Human long-form story quality, final art/audio and accessibility review']
 accepted={'runtime_source_commit':manifest['source_commit'],'runtime_files':manifest['runtime_files'],'unit_tests':{'passed':count,'failed':0,'skipped':0},'tests':tests,'campaigns':campaigns['campaigns'],'campaign_scope':'All accepted campaigns and independently extracted suites use the manifest runtime hashes exactly; superseded attempts excluded','not_run':missing,'passed':True,'full_phase35_complete':False};(a.output/'accepted_summary.json').write_text(json.dumps(accepted,indent=2))
 lines=['# Phase 3.5 measured validation','', 'Status: substantial working increment verified within the explicit limits below. **Full Phase 3.5/final audiovisual production is not declared complete.** See PHASE35_LIMITATIONS.md and FINAL_RELEASE_ROADMAP.md.','',f'Runtime tested from **{manifest["source_commit"]}** through an independently extracted source-based Lite ZIP, with **63 runtime files**. Final packaging may update documentation; runtime hashes must stay identical. All accepted campaign runtime hashes match this independent extraction exactly. Final packaging may update documentation only; runtime identity is checked again before publishing.','', '## Final extracted Lite automated results','', '| Suite | Actual result |','| --- | --- |',f'| Node deterministic cases | {count} passed, 0 failed, 0 skipped |']
 for n in ['cinematic','stability','compatibility','production','bridge']:lines.append(f'| {n} Chromium suite | {tests[n]["tests_run"]} passed |')
 lines+=['| Pixel 5 touch/mobile flow | '+str(len(tests['mobile_functional']['checks']))+' checks passed; actual HTTP, stubbed host input/TV |',f'| Static/dependency/manifest | {tests["static"]["syntax_files"]} syntax files; {tests["static"]["local_scripts"]} local script dependencies; all retained hashes verified |','','Browser suites overlap inherited cases; counts are executions, not distinct scenarios. Tests run outside Lite against extracted assets. Positive extraordinary-lethal tests use explicitly authored fixtures, not claimed natural campaign clips.','', '## Real backup migration','', '| Backup | History records in receiving browser | Tick resumed | Result |','| --- | --- | --- | --- |']
 for n in ['migrate_phase1','migrate_phase2','migrate_phase3','migrate_phase3_loss','migrate_phase35']:
  r=tests[n];lines.append(f'| {n} | {r["imported_history_records"]} | {r["imported_tick"]} → {r["resumed_tick"]} | Original compared domains, full history IDs and exact reload preserved |')
 lines+=['','Legacy Phase 1/2/3 and new Phase 3.5 complete backups preserve the compared original domains, all supplied history IDs and exact reload/resume. The verified new empty source-frame field is the only allowed cinema migration difference for old saves. Save-only v1.3 imports preserve available records and explicitly label incomplete older archives; Core/Extended isolation is retained. Initial two-minute harness timeouts and the reproduced late-cancel failure are retained as diagnostics, excluded from accepted results.','', '## Continuous campaigns','', 'Fixed start 2026-10-28 00:00 UTC, America/Chicago. Production physical/calendar controllers process hourly real intervals; test-driver per-step autosave is disabled, actual saves/checkpoint reloads asserted. Thirty real days equal 111.75 simulated days due to synchronized 1× holidays; seven equal 25.0. Adverse initial states use asserted normal backup-import fixtures, not natural-event claims.','', '| Profile | Real / simulated days | Alive / dead | Arrivals | Field / local jobs | Conversations | Films / awards |','| --- | --- | --- | --- | --- | --- | --- |']
 for name,r in campaigns['campaigns'].items():lines.append(f'| {name} | {r["real_days"]} / {r["sim_days"]} | {r["alive"]} / {len(r["dead"])} | {r["arrivals"]} | {r["field_missions"]} / {r["local_jobs"]} | {r["conversations"]} | {r["weekly_films"]} / {r["film_award_segments"]} |')
 lines+=['','Daily resource/frontier/chronicle/knowledge/creature/cinematic audits pass, all original crew identities remain accounted for, wall time is not discarded/rewound and checkpoint reloads match. Independent full-history audits find no private/missing public film/SOL sources or invalid snapshot provenance. Real travel/objectives are required; survival alone is insufficient.','', 'Deaths and their actual causes, if any, are listed in campaign_summary.json. Survival is not manufactured or treated as the sole acceptance gate. Legendary positive-path tests use retained raw-evidence fixtures; ordinary deaths, insufficient samples and missing imagery are excluded.','', '## Sources, science, resources and growth','']
 for name,r in campaigns['campaigns'].items():
  lines.append(f'- **{name}:** {r["history_records"]} full history records; {r["science_cases"]} science cases; experiment statuses {json.dumps(r["experiment_statuses"],sort_keys=True)}; {r["captured_state_frames"]} actual captured state frames, {r["retained_visual_frames"]} retained; {r["film_recorded_segments"]} sourced recorded film segments, {r["film_legendary_segments"]} Legendary segments. Film durations: {r["film_durations_seconds"]} seconds. Primary compressed cache: {r["storage_first"]["primary_bytes"]} → {r["storage_last"]["primary_bytes"]} bytes. Travel fuel: {r["travel_fuel"]}.')
 lines+=['','## Editorial and streamed-history evidence','', 'The baseline ordinary runs repeated the same unchanged HR follow-up 300/301 times. New actual counts: '+', '.join(name+' '+str(r['grievance_followups']) for name,r in campaigns['campaigns'].items())+'. This measures recurrence, not human literary quality. Actual excerpts/source IDs and top repeated text are retained for human review.', '', 'Actual streamed roundtrip: '+str(tests['streaming']['history_records'])+' history records, '+str(tests['streaming']['export_bytes'])+' bytes; cursor export '+str(round(tests['streaming']['export_seconds'],2))+' seconds, staged NDJSON import '+str(round(tests['streaming']['stream_import_seconds'],2))+' seconds. The history getAll method was forbidden; real OPFS writable-file APIs and exact source/world/reload equality were checked. Native OS chooser behavior was not claimed. API cancellation, corrupt/truncated chunks, transaction abort, writer collisions/fencing, LAN lease fallback, late cancellation and future-schema protection are exercised separately by the refinement suite.', '']
 lines+=['','Complete resource balances/acquisition, source-kind diversity, repeated social text counts, checkpoints, fatality causal windows and runtime/backup SHA-256 values are in reports/phase35/campaign_summary.json and accepted_summary.json. Resource audits retain finite production/conversion/consumption/transfer identities; Phase 3.5 adds no free-resource source. Sparse frames mean reconstruction cards are common. Short quiet archives are intentional, not filled with invented scenes.','', '## Performance and unavailable gates','']
 p=tests['performance'];lines.append(f'{p["samples"]} paused synchronous camera refreshes: mean {p["mean_ms"]:.3f} ms, p95 {p["p95_ms"]:.3f} ms, max {p["max_ms"]:.3f} ms. Actor rebuild counter {p["before"]["actorRebuilds"]} → {p["after"]["actorRebuilds"]}; world snapshot unchanged. Heap samples and Linux campaign RSS series are retained separately. Timings under concurrent headless load are not native GPU/compositor FPS or a proof of no multi-year leak.')
 memory=json.loads((reports/'campaign_memory.json').read_text());peaks={}
 for sample in memory['samples']:
  for name,v in sample['campaigns'].items():peaks[name]=max(peaks.get(name,0),v['sum_rss_kib'])
 lines+=['', 'Linux campaign process-tree RSS peaks (MiB): '+', '.join(name.split('--output ')[-1].split('/')[-1]+' '+str(round(value/1024,1)) for name,value in peaks.items())+'. This includes Python harness, browser and shared pages counted more than once; it is not retained game JS heap or Android thin-client memory. Full timestamp samples are retained.', '']
 lines+=['','Source frames 24, routine memories 24/person, choices 12/person, snapshots 120, SOL notes 48 and films 12 weeks are bounded; full history/knowledge still grow. Live-state growth, legacy-format memory use and wider platform/human review remain open.','', 'Not run: '+ '; '.join(missing)+'. No antivirus bypass or native-hardware certification is implied.','', 'Superseded diagnostic failures/campaigns are identified in engineering notes and excluded from accepted totals. Procedural motion, optional source-backed awards, conservative automatic lethal classification, staged streaming transfers and single-writer protection are implemented and tested. Native hardware/antivirus and sustained human cinematic review remain blocked by unavailable facilities. No final-release or full-phase completion is declared. Next batch: execute native/human gates, review story examples and retained-heap performance, and improve live-state/legacy JSON scaling before additional scope.']
 Path('PHASE35_VALIDATION.md').write_text('\n'.join(lines)+'\n');print('Accepted Phase 3.5 automated implementation; native and human completion gates remain unverified.')
if __name__=='__main__':main()
